 await f().getByRole('button',{name:'Rename',exact:true}).first().click();await f().getByLabel('Conversation title',{exact:true}).fill(threadTitle+' renamed');await f().getByRole('button',{name:'Save title',exact:true}).click();threadTitle+=' renamed';await f().locator('.thread-open').filter({hasText:threadTitle}).waitFor();check('Rename persists in saved History');
